/* @lc app=leetcode id=4007 lang=kotlin */ class Solution { fun maximumWidth(planks: IntArray): Int = planks.toList().groupingBy { it }.eachCount().let { c -> c.keys.toList().let { v -> HashMap<Long, Int>().also { pr -> v.indices.forEach { i -> (i until v.size).forEach { j -> pr.merge(v[i].toLong() + v[j], if (i == j) c[v[i]]!! / 2 else minOf(c[v[i]]!!, c[v[j]]!!)) { a, b -> a + b } } } }.let { pr -> (pr.keys + v.map { it.toLong() }).maxOf { h -> (pr[h] ?: 0) + (if (h <= 1_000_000_000L) c[h.toInt()] ?: 0 else 0) } } } } }